#include "LogisticsProductionSubsystem.h"
FWorldOperationResult ULogisticsProductionSubsystem::Failure(EWorldOperationResultCode C,const FGuid& O,const TCHAR* M)const{return FWorldOperationResult::Failure(C,O,FText::FromString(M));}
FWorldOperationResult ULogisticsProductionSubsystem::ValidateOperation(const FGuid& O)const{if(!O.IsValid())return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Operation ID must be valid."));if(ProcessedOperationIds.Contains(O))return Failure(EWorldOperationResultCode::Conflict,O,TEXT("Operation ID already processed."));return FWorldOperationResult::Success(O,FText::GetEmpty(),{});}
void ULogisticsProductionSubsystem::RememberOperation(const FGuid& O){if(O.IsValid())ProcessedOperationIds.Add(O);}
FWorldOperationResult ULogisticsProductionSubsystem::RegisterContainer(FTransportContainerState& C,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(!FMath::IsFinite(C.Capacity)||C.Capacity<=0||!FMath::IsFinite(C.UsedCapacity)||C.UsedCapacity<0||C.UsedCapacity>C.Capacity)return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Container capacity invalid."));if(!C.ContainerId.IsValid())C.ContainerId=FGuid::NewGuid();if(Containers.Contains(C.ContainerId))return Failure(EWorldOperationResultCode::Conflict,O,TEXT("Container ID already exists."));C.Revision=1;Containers.Add(C.ContainerId,C);RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Container registered.")),{C.ContainerId});}
FWorldOperationResult ULogisticsProductionSubsystem::TransferResource(FGuid A,FGuid B,FName R,double Q,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;FTransportContainerState* S=Containers.Find(A);FTransportContainerState* T=Containers.Find(B);if(!S||!T||A==B||R.IsNone()||!FMath::IsFinite(Q)||Q<=0)return Failure(EWorldOperationResultCode::InvalidTarget,O,TEXT("Transfer endpoints or quantity invalid."));int32 SI=INDEX_NONE,TI=INDEX_NONE;for(int32 I=0;I<S->Contents.Num();++I)if(S->Contents[I].ResourceId==R){SI=I;break;}for(int32 I=0;I<T->Contents.Num();++I)if(T->Contents[I].ResourceId==R){TI=I;break;}if(SI==INDEX_NONE||S->Contents[SI].Quantity<Q)return Failure(EWorldOperationResultCode::InsufficientResources,O,TEXT("Source stock insufficient."));const FName Unit=S->Contents[SI].UnitId;if(Unit.IsNone()||(TI!=INDEX_NONE&&T->Contents[TI].UnitId!=Unit))return Failure(EWorldOperationResultCode::Conflict,O,TEXT("Resource units do not match."));const double Volume=Q;if(T->UsedCapacity+Volume>T->Capacity)return Failure(EWorldOperationResultCode::CapacityExceeded,O,TEXT("Target capacity exceeded."));S->Contents[SI].Quantity-=Q;if(S->Contents[SI].Quantity<=KINDA_SMALL_NUMBER)S->Contents.RemoveAt(SI);if(TI==INDEX_NONE){FLogisticsResourceStack N;N.ResourceId=R;N.Quantity=Q;N.UnitId=Unit;T->Contents.Add(N);}else T->Contents[TI].Quantity+=Q;S->UsedCapacity=FMath::Max(0.0,S->UsedCapacity-Volume);T->UsedCapacity+=Volume;++S->Revision;++T->Revision;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Resource transfer committed.")),{A,B});}
FWorldOperationResult ULogisticsProductionSubsystem::RegisterRecipe(const FProductionRecipeDefinition& R,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(R.RecipeId.IsNone()||Recipes.Contains(R.RecipeId)||R.Inputs.IsEmpty()||R.Outputs.IsEmpty()||!FMath::IsFinite(R.DurationSeconds)||R.DurationSeconds<0)return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Recipe definition invalid."));for(const auto& X:R.Inputs)if(!X.IsValid()||X.Quantity<=0)return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Recipe input invalid."));for(const auto& X:R.Outputs)if(!X.IsValid()||X.Quantity<=0)return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Recipe output invalid."));Recipes.Add(R.RecipeId,R);RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Recipe registered.")),{});}
FWorldOperationResult ULogisticsProductionSubsystem::QueueProduction(FName R,FGuid& Out,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(!Recipes.Contains(R))return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Recipe not registered."));FProductionJob J;J.JobId=FGuid::NewGuid();J.RecipeId=R;J.Revision=1;Jobs.Add(J.JobId,J);Out=J.JobId;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Job queued; resource reservation not integrated.")),{J.JobId});}
FWorldOperationResult ULogisticsProductionSubsystem::AdvanceProduction(FGuid Id,float D,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;FProductionJob* J=Jobs.Find(Id);if(!J||J->State==EProductionJobState::Completed||J->State==EProductionJobState::Cancelled||!FMath::IsFinite(D)||D<=0)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Job or delta invalid."));const auto* R=Recipes.Find(J->RecipeId);if(!R)return Failure(EWorldOperationResultCode::MissingConfiguration,O,TEXT("Recipe missing."));J->State=EProductionJobState::Running;J->ProgressSeconds+=D;if(J->ProgressSeconds>=R->DurationSeconds){J->ProgressSeconds=R->DurationSeconds;J->State=EProductionJobState::Completed;}++J->Revision;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Production ledger advanced; outputs are not materialized.")),{Id});}
FWorldOperationResult ULogisticsProductionSubsystem::CancelProduction(FGuid Id,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;auto* J=Jobs.Find(Id);if(!J||J->State==EProductionJobState::Completed||J->State==EProductionJobState::Cancelled)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Job cannot be cancelled."));J->State=EProductionJobState::Cancelled;++J->Revision;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Job cancelled; no inputs were consumed.")),{Id});}
float ULogisticsProductionSubsystem::CalculateRouteCost(float D,float P,bool Road)const{if(!FMath::IsFinite(D)||!FMath::IsFinite(P)||D<0||P<0)return TNumericLimits<float>::Max();return D*(1+P)*(Road?0.65f:1.0f);}
FWorldOperationResult ULogisticsProductionSubsystem::UpdateSurvival(FSurvivalState& S,float D,float Temp,float Rain,bool Shelter,bool Rest,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(!FMath::IsFinite(D)||D<=0||!FMath::IsFinite(Temp)||!FMath::IsFinite(Rain)||Rain<0)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Survival tick inputs invalid."));FSurvivalState N=S;const float H=D/3600.0f;N.Hunger=FMath::Clamp(N.Hunger-H,0.0f,100.0f);N.Thirst=FMath::Clamp(N.Thirst-1.5f*H,0.0f,100.0f);N.Fatigue=FMath::Clamp(N.Fatigue+(Rest?-3.0f:1.0f)*H,0.0f,100.0f);N.Wetness=FMath::Clamp(N.Wetness+(Shelter?0.0f:Rain*5.0f-0.5f)*H,0.0f,100.0f);const float Cold=FMath::Max(0.0f,10.0f-Temp),Heat=FMath::Max(0.0f,Temp-30.0f);N.Warmth=FMath::Clamp(N.Warmth-(Cold*0.8f+N.Wetness*0.02f-(Shelter?5.0f:0.0f))*H,0.0f,100.0f);if(N.Hunger<=0||N.Thirst<=0||N.Warmth<=0)N.Health=FMath::Clamp(N.Health-2.0f*H,0.0f,100.0f);if(!Shelter&&Heat>0)N.Health=FMath::Clamp(N.Health-Heat*0.01f*H,0.0f,100.0f);N.Stamina=FMath::Clamp(N.Stamina+(Rest?5.0f:-2.0f)*H,0.0f,100.0f);++N.Revision;S=N;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Prototype survival tick applied; tune rates.")),{});}
FWorldOperationResult ULogisticsProductionSubsystem::ApplyExposure(FSurvivalState& S,ESurvivalExposureType T,float X,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(!FMath::IsFinite(X)||X<0||X>100)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Severity must be 0..100."));FSurvivalState N=S;switch(T){case ESurvivalExposureType::Cold:N.Warmth=FMath::Clamp(N.Warmth-X,0.0f,100.0f);break;case ESurvivalExposureType::Heat:N.Health=FMath::Clamp(N.Health-X*0.1f,0.0f,100.0f);break;case ESurvivalExposureType::Wetness:N.Wetness=FMath::Clamp(N.Wetness+X,0.0f,100.0f);break;case ESurvivalExposureType::Hunger:N.Hunger=FMath::Clamp(N.Hunger-X,0.0f,100.0f);break;case ESurvivalExposureType::Thirst:N.Thirst=FMath::Clamp(N.Thirst-X,0.0f,100.0f);break;case ESurvivalExposureType::Fatigue:N.Fatigue=FMath::Clamp(N.Fatigue+X,0.0f,100.0f);break;case ESurvivalExposureType::Injury:N.InjurySeverity=FMath::Clamp(N.InjurySeverity+X,0.0f,100.0f);break;case ESurvivalExposureType::Illness:N.IllnessSeverity=FMath::Clamp(N.IllnessSeverity+X,0.0f,100.0f);break;case ESurvivalExposureType::Poisoning:N.PoisoningSeverity=FMath::Clamp(N.PoisoningSeverity+X,0.0f,100.0f);break;}++N.Revision;S=N;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Exposure applied.")),{});}
FWorldOperationResult ULogisticsProductionSubsystem::RegisterFood(FFoodQualityRecord& F,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(!FMath::IsFinite(F.Quality)||!FMath::IsFinite(F.SpoilagePerWorldHour)||F.Quality<0||F.Quality>100||F.SpoilagePerWorldHour<0)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Food quality config invalid."));if(!F.FoodId.IsValid())F.FoodId=FGuid::NewGuid();if(Foods.Contains(F.FoodId))return Failure(EWorldOperationResultCode::Conflict,O,TEXT("Food ID already exists."));Foods.Add(F.FoodId,F);RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Food record registered.")),{F.FoodId});}
FWorldOperationResult ULogisticsProductionSubsystem::AdvanceFoodQuality(FGuid Id,double Hour,bool Preserved,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;auto* F=Foods.Find(Id);if(!F||!FMath::IsFinite(Hour)||Hour<F->LastProcessedWorldHour)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Food missing or time moved backwards."));F->Quality=FMath::Clamp(F->Quality-FMath::Max(0.0,Hour-F->LastProcessedWorldHour)*F->SpoilagePerWorldHour*(Preserved?0.1:1.0),0.0f,100.0f);F->LastProcessedWorldHour=Hour;RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Food quality advanced.")),{Id});}
FWorldOperationResult ULogisticsProductionSubsystem::RecordDiscovery(FWorldDiscoveryRecord& D,double Hour,FGuid O){auto V=ValidateOperation(O);if(!V.IsSuccess())return V;if(D.DiscoveryDefinitionId.IsNone()||!FMath::IsFinite(Hour)||Hour<0)return Failure(EWorldOperationResultCode::InvalidState,O,TEXT("Discovery definition or time invalid."));if(!D.DiscoveryId.IsValid())D.DiscoveryId=FGuid::NewGuid();if(Discoveries.Contains(D.DiscoveryId))return Failure(EWorldOperationResultCode::Conflict,O,TEXT("Discovery already recorded."));D.DiscoveredAtWorldHour=Hour;Discoveries.Add(D.DiscoveryId,D);RememberOperation(O);return FWorldOperationResult::Success(O,FText::FromString(TEXT("Discovery recorded in transient ledger.")),{D.DiscoveryId});}
TArray<FProductionJob> ULogisticsProductionSubsystem::GetProductionJobs()const{TArray<FProductionJob> R;Jobs.GenerateValueArray(R);return R;}
TArray<FWorldDiscoveryRecord> ULogisticsProductionSubsystem::GetDiscoveries()const{TArray<FWorldDiscoveryRecord> R;Discoveries.GenerateValueArray(R);return R;}
